# Check exact mapping per row
for row_idx in range(len(grid)):
    left = left_region[row_idx]
    right = right_region[row_idx]

    # Build the exact per-row mapping
    row_map = {}
    for j, (l, r) in enumerate(zip(left, right)):
        if l not in row_map:
            row_map[l] = r

    print(f"Row {row_idx} mapping:")
    for k, v in sorted(row_map.items()):
        print(f"  {k} -> {v}")

# Check if mapping depends on position index
for row_idx in range(len(grid)):
    left = left_region[row_idx]
    right = right_region[row_idx]

    # Group right values by their position
    pos_map = {}
    for j, r in enumerate(right):
        pos_map.setdefault(v:=right[j], []).append(j)

    print(f"\nRow {row_idx}: Right value {v} at positions {pos_map[v]}")
    for v, pos in sorted(pos_map.items()):
        lats = [left[j] for j in pos]
        print(f"  Right value {v} occurs at positions {pos}, with left values {lats}")

